window.CARDS=window.CARDS||{};CARDS["people-asahina-nazuna"]=[{"i":"sc-asahina-nazuna-y1v8-p173-1","v":"y1v8","y":1,"o":10,"k":"","w":"asahina-nazuna","q":"asahina nazuna ch 6 9  passing mentions named when ayanokoji looks up the class c girl who ate with hashimoto  later cited as an information source  full name printed   that person was named asahina nazuna  cited alongside kei as a source of post exam information","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v8-p173-1\"><h3><span class=\"ttl\">Ch.6/9: passing mentions<\/span><span class=\"meta\">Y1V8 · p.173, 232<\/span><\/h3><p class=\"setup\">Named when Ayanokōji looks up the Class C girl who ate with Hashimoto; later cited as an information source.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Full name printed: “That person was named Asahina Nazuna.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Cited alongside Kei as a source of post-exam information.<span class=\"pg\">p.232<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y1v8-p174-1\">→ After: Ch.6: the charm bargain and the Nagumo picture<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y1v8-p174-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi horikita-manabu tachibana-akane asahina-nazuna","q":"asahina nazuna ch 6  the charm bargain and the nagumo picture second year class a  met outside the bathroom after ayanokoji follows her alone from dinner   i m going to the bathroom  be right back   they don t sell this charm at the school anymore  though   wait  are you the person who found my charm   no  i think i m right  i see  so it was you   thank you  when i realized i d lost it  i was so upset  ever since then  i ve been scared i ll lose it again  so i ve been wearing it more often   this charm  well  i bought it after i started school  it s not like i have any strong attachment to it in itself or anything  it s just how do i put it  it s like emotional support   i never imagined you d be the one who found it   yeah  i know about you  you got a lot of attention in that relay race against horikita senpai   nagumo really respects horikita senpai  or  like  he s made horikita senpai a sort of goal  i think he was probably jealous that he didn t get to challenge him during the relay   well  how about you beat him at something  you could cut that smug miyabi down to size  personally  i d love to see him lose for once   ah ha ha ha  come on  i was joking  couldn t you tell   wait  are you serious   hey  look  this isn t something a first year can do anything about   the most straightforward   that s some dangerous talk  i m a second year too  you know  miyabi and i have a pretty deep relationship  understand   i think those are similar things  though   ah  wait  somehow  i feel like i m the bad guy here   i see you re not joking around  as an apology  please let me repay you for picking up my charm  if there s anything you d like to know  i ll tell you   to be honest  i don t think anything drastic will happen just because i talk to you   girls who are close with him  like  all of them  they trust miyabi more than other guys  y know   you really think i d tell you that   wow  you re cheeky   well  if i do say so myself  the second years have a really strong sense of unity  honestly  we were more successful at dividing into groups than the first  and the third years  you know  after they explained the test to us back on the bus  miyabi said to immediately share that information with the other classes   for the most part  yeah   why do you ask   no  i will  it s just when we were deciding on the large groups  some of the second year girls made a small request  or more like they wanted some adjustments  at that time  the small group was made up of members that miyabi could count on   even if you ask me that  i hardly know anything about the first years  from the third years  i guess there s tachibana senpai  who was horikita senpai s secretary   he always sticks to his word  he won t use dirty tricks  besides  even if that group of girls does try to lay some kind of trap  it won t have any effect on horikita senpai and miyabi s fight   what i can tell you  i suppose  is that whoever cares too much is the one who loses   well  do your best to try and give miyabi a run for his money  boy   i ll be rooting for you  even if it s only a little bit  charm finder revealed  repays with second year intel  reads him as cheeky but not a real threat to miyabi  close classmate    miyabi and i have a pretty deep relationship  vouches fair square   whoever cares too much  is her warning  nagumo s goal jealousy frame  tachibana named as his secretary in the girls  large group  named as horikita senpai s secretary inside the adjusted large group  representative is someone else  rough exterior and dutiful reputation  does not worship nagumo  honest type in ayanokoji s read  jokes then repays seriously  lays out second year unity  bus time info sharing  and the girls  group request without flinching   hardly know anything about the first years  won t name nagumo s eyes and ears","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v8-p174-1\"><h3><span class=\"ttl\">Ch.6: the charm bargain and the Nagumo picture<\/span><span class=\"meta\">Y1V8 · p.174–181<\/span><\/h3><p class=\"setup\">Second-year Class A; met outside the bathroom after Ayanokōji follows her alone from dinner.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"tachibana-akane.html\">Tachibana Akane<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m going to the bathroom. Be right back.”<span class=\"pg\">p.174<\/span><\/li><li class=\"q spoken\">“They don’t sell this charm at the school anymore, though”<span class=\"pg\">p.175<\/span><\/li><li class=\"q spoken\">“Wait, are you…the person who found my charm?”<span class=\"pg\">p.175<\/span><\/li><\/ul><details class=\"more\"><summary>35 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No, I think I’m right. I see. So it was you”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you. When I realized I’d lost it, I was so upset. Ever since then, I’ve been scared I’ll lose it again, so I’ve been wearing it more often.”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This charm, well, I bought it after I started school. It’s not like I have any strong attachment to it in itself or anything. It’s just…how do I put it? It’s like emotional support.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I never imagined you’d be the one who found it.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I know about you. You got a lot of attention in that relay race against Horikita-senpai.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo really respects Horikita-senpai. Or, like, he’s made Horikita-senpai a sort of goal. I think he was probably jealous that he didn’t get to challenge him during the relay.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, how about you beat him at something? You could cut that smug Miyabi down to size. Personally, I’d love to see him lose for once”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah ha ha ha! Come on, I was joking. Couldn’t you tell?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, are you serious?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, look. This isn’t something a first-year can do anything about”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The most straightforward?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s some dangerous talk. I’m a second-year too, you know. Miyabi and I have a pretty deep relationship, understand?”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think those are similar things, though”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, wait. Somehow, I feel like I’m the bad guy here”<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see you’re not joking around. As an apology, please let me repay you for picking up my charm. If there’s anything you’d like to know, I’ll tell you.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To be honest, I don’t think anything drastic will happen just because I talk to you”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Girls who are close with him? Like, all of them. They trust Miyabi more than other guys, y’know.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You really think I’d tell you that?”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow, you’re cheeky”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, if I do say so myself, the second-years have a really strong sense of unity. Honestly, we were more successful at dividing into groups than the first- and the third-years, you know? After they explained the test to us back on the bus, Miyabi said to immediately share that information with the other classes.”<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “For the most part, yeah.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why do you ask?”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I will. It’s just…when we were deciding on the large groups, some of the second-year girls made a small request. Or more like…they wanted some adjustments. At that time, the small group was made up of members that Miyabi could count on.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if you ask me that, I hardly know anything about the first-years. From the third-years, I guess there’s Tachibana-senpai, who was Horikita-senpai’s secretary.”<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He always sticks to his word. He won’t use dirty tricks. Besides, even if that group of girls does try to lay some kind of trap, it won’t have any effect on Horikita-senpai and Miyabi’s fight.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What I can tell you, I suppose, is that whoever cares too much is the one who loses.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, do your best to try and give Miyabi a run for his money, boy”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be rooting for you, even if it’s only a little bit.”<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Charm finder revealed; repays with second-year intel; reads him as cheeky but not a real threat to Miyabi.<span class=\"pg\">p.175–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Close classmate — “Miyabi and I have a pretty deep relationship”; vouches fair-square; “whoever cares too much” is her warning.<span class=\"pg\">p.176–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Nagumo’s goal/jealousy frame; Tachibana named as his secretary in the girls’ large group.<span class=\"pg\">p.176, 180–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tachibana Akane<\/b> Named as Horikita-senpai’s secretary inside the adjusted large group (representative is someone else).<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Rough exterior and dutiful reputation; does not worship Nagumo; honest type in Ayanokōji’s read; jokes then repays seriously.<span class=\"pg\">p.174–179<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Lays out second-year unity, bus-time info sharing, and the girls’ group request without flinching.<span class=\"pg\">p.179–181<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> “hardly know anything about the first-years”; won’t name Nagumo’s eyes and ears.<span class=\"pg\">p.179–180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y1v8-p173-1\">← Before: Ch.6/9: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y1v8-p238-1\">→ After: Ch.9: named as an information source<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y1v8-p238-1","v":"y1v8","y":1,"o":10,"k":"","w":"ayanokouji-kiyotaka ichinose-honami karuizawa-kei asahina-nazuna","q":"asahina nazuna ch 9  named as an information source one of the three people ayanokoji credits for the tachibana conclusion   that was the conclusion i d drawn after piecing together information from kei  ichinose  and asahina  source in the info chain behind the trap read  also earlier gave him the group s composition intel  same source list  same source list   kei is the one he is speaking to  mention only   no scene presence in this chapter","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v8-p238-1\"><h3><span class=\"ttl\">Ch.9: named as an information source<\/span><span class=\"meta\">Y1V8 · p.238<\/span><\/h3><p class=\"setup\">One of the three people Ayanokōji credits for the Tachibana conclusion.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “That was the conclusion I’d drawn after piecing together information from Kei, Ichinose, and Asahina.”<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Source in the info chain behind the trap read; also earlier gave him the group’s composition intel.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Same source list.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Same source list — Kei is the one he is speaking to.<span class=\"pg\">p.238<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Mention only — no scene presence in this chapter.<span class=\"pg\">p.238<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y1v8-p174-1\">← Before: Ch.6: the charm bargain and the Nagumo picture<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y1v10-p96-1","v":"y1v10","y":1,"o":12,"k":"action spoken","w":"ichinose-honami nagumo-miyabi ayanokouji-kiyotaka asahina-nazuna","q":"asahina nazuna ch 3  conversation with ayanokoji greets ichinose and borrows ayanokoji to speak with him alone   good morning honami  tells ayanokoji ichinose cares deeply for her friends and would not sit back  reveals ichinose asked nagumo for points and nagumo consented   bingo again  reveals nagumo s condition is for the two of them to get into a relationship   the condition he set for lending the points to her  is for the two of them to get into a relationship  says she hopes ayanokoji can do something  he says he cannot  speaks on her behalf about the deal with nagumo  reveals his condition for lending points  asks him to help ichinose   sorry honami  see ya   she s a real good kid isn t she  cute  smart  even among the second years  nobody has anything bad to say about her   could it be that you ve managed to gain her affection   how boring  well whatever  i happened to see the two of you acting all buddy buddy  so i wanted to tell you something   honami cares deeply for her friends  or how should i put it  you know she s not the type of person who would sit back and let someone from class b be expelled  right   it seems she s gone and asked miyabi for assistance  can you guess how he responded   of course there isn t  sure  it d be a different story if we were only talking about a few thousand points  in that case  there d be plenty of room for discussion  but once it gets into the hundred thousands or the millions  nobody s gonna give away that many   the condition he set for lending the points to her  is for the two of them to get into a relationship   i ve already told you  it s for my class  if miyabi lends all those private points to a first year  the rest of us may suffer as a result  furthermore  in exchange for protecting her friends  honami ll have to go through something painful   i dunno  but  if it s you  you ll probably be able to do something about it one way or another   that s okay  even if you don t do anything  i won t hold it against you  it s just wishful thinking on my part either way  that said  even though you say you can t  i think you just might take the chance anyway  slaps ayanokoji on the back and runs toward the school after asking him to help","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v10-p96-1\"><h3><span class=\"ttl\">Ch.3: Conversation with Ayanokōji<\/span><span class=\"meta\">Y1V10 · p.96–103<\/span><\/h3><p class=\"setup\">Greets Ichinose and borrows Ayanokōji to speak with him alone. Tells Ayanokōji Ichinose cares deeply for her friends and would not sit back. Reveals Ichinose asked Nagumo for points and Nagumo consented. Reveals Nagumo’s condition is for the two of them to get into a relationship. Says she hopes Ayanokōji can do something; he says he cannot.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Good morning Honami.”<span class=\"pg\">p.96<\/span><\/li><li class=\"q spoken\">“Bingo again.”<span class=\"pg\">p.99<\/span><\/li><li class=\"q spoken\">“The condition he set for lending the points to her… is for the two of them to get into a relationship.”<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Speaks on her behalf about the deal with Nagumo.<span class=\"pg\">p.96–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Reveals his condition for lending points.<span class=\"pg\">p.99–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks him to help Ichinose.<span class=\"pg\">p.96–103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry Honami. See ya.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s a real good kid isn’t she? Cute. Smart. Even among the second-years, nobody has anything bad to say about her.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could it be that you’ve managed to gain her affection?”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How boring. Well whatever. I happened to see the two of you acting all buddy buddy, so I wanted to tell you something.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honami cares deeply for her friends, or how should I put it… You know she’s not the type of person who would sit back and let someone from Class B be expelled, right?”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems she’s gone and asked Miyabi for assistance. Can you guess how he responded?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course there isn’t. Sure, it’d be a different story if we were only talking about a few thousand points. In that case, there’d be plenty of room for discussion. But once it gets into the hundred thousands or the millions? Nobody’s gonna give away that many.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The condition he set for lending the points to her… is for the two of them to get into a relationship.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve already told you. It’s for my class. If Miyabi lends all those private points to a first-year, the rest of us may suffer as a result. Furthermore, in exchange for protecting her friends, Honami’ll have to go through something painful.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I dunno. But, if it’s you, you’ll probably be able to do something about it one way or another.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s okay. Even if you don’t do anything, I won’t hold it against you. It’s just wishful thinking on my part either way. That said, even though you say you can’t, I think you just might take the chance anyway.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Slaps Ayanokōji on the back and runs toward the school after asking him to help.<span class=\"pg\">p.103<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-asahina-nazuna-y1v11_5-p94-1","v":"y1v11.5","y":1,"o":14,"k":"","w":"nagumo-miyabi horikita-manabu horikita-suzune kiriyama-ikuto asahina-nazuna","q":"asahina nazuna ch 1  graduation farewells asahina nazuna appears with nagumo miyabi and other student council members during the third year farewells  she questions nagumo when he says he did not lose to horikita manabu despite manabu graduating from class a  she presses nagumo on what counts as losing in his conflict with horikita manabu  accompanies him and questions his view of the outcome  present during farewells involving the former student council president  present nearby when nagumo approaches suzune  present with him among student council members","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y1v11_5-p94-1\"><h3><span class=\"ttl\">Ch.1: Graduation farewells<\/span><span class=\"meta\">Y1V11.5 · p.94–104<\/span><\/h3><p class=\"setup\">Asahina Nazuna appears with Nagumo Miyabi and other student council members during the third-year farewells. She questions Nagumo when he says he did not lose to Horikita Manabu despite Manabu graduating from Class A. She presses Nagumo on what counts as losing in his conflict with Horikita Manabu.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Accompanies him and questions his view of the outcome.<span class=\"pg\">p.94–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Present during farewells involving the former student council president.<span class=\"pg\">p.94–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Present nearby when Nagumo approaches Suzune.<span class=\"pg\">p.98–104<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiriyama Ikuto<\/b> Present with him among student council members.<span class=\"pg\">p.94–104<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-asahina-nazuna-y2v3-p130-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi asahina-nazuna","q":"asahina nazuna asahina at the beach she stops playing in the ocean and sidles up to ayanokoji once nagumo steps away  her whispered advice is swallowed by nagumo s return   it wasn t just nagumo either  asahina and several other third year students had also rented swimsuits    named as a swimsuit renter alongside nagumo  not present  pov ayanokoji   heyo  word is that you re working alone   well  you probably heard me earlier  but i ve got a tough fight ahead of me   that so  maybe that s for the best though  if miyabi were to start goin  after you  things d prolly get pretty dicey for ya  yeah  so here s some advice  while you ve got the chance  go meet up with as many groups as possible and   asahina  it s time  let s get going   w well  good luck  opportunistic warner  her advice cuts off halfway  the rest he infers himself  her leader  she keeps playing along","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v3-p130-1\"><h3><span class=\"ttl\">Asahina at the beach<\/span><span class=\"meta\">Y2V3 · p.130–132<\/span><\/h3><p class=\"setup\">She stops playing in the ocean and sidles up to Ayanokōji once Nagumo steps away; her whispered advice is swallowed by Nagumo&#x27;s return.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Heyo. Word is that you’re working alone?”<span class=\"pg\">p.132<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Well. You probably heard me earlier, but I’ve got a tough fight ahead of me.”<span class=\"pg\">p.132<\/span><\/li><li class=\"q spoken\">“That so…? Maybe that’s for the best though. If Miyabi were to start goin’ after you… things’d prolly get pretty dicey for ya, yeah? So here’s some advice. While you’ve got the chance, go meet up with as many groups as possible…”<span class=\"pg\">p.132<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “It wasn’t just Nagumo either. Asahina and several other third-year students had also rented swimsuits.” — named as a swimsuit renter alongside Nagumo; not present; POV Ayanokōji.<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That so…? Maybe that’s for the best though. If Miyabi were to start goin’ after you… things’d prolly get pretty dicey for ya, yeah? So here’s some advice. While you’ve got the chance, go meet up with as many groups as possible and───”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Asahina, it’s time. Let’s get going.”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “W-well, good luck.”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Opportunistic warner; her advice cuts off halfway; the rest he infers himself.<span class=\"pg\">p.131–132<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Her leader; she keeps playing along.<span class=\"pg\">p.131–132<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-asahina-nazuna-y2v5-p22-1","v":"y2v5","y":2,"o":21,"k":"spoken","w":"satou-maya matsushita-chiaki maezono horikita-suzune asahina-nazuna","q":"asahina nazuna mii chan  the maid cafe proposal writer sitting in the special wing classroom in a chinese style maid suit for the  maimai  maid cafe demonstration  shyly watching the customers  sato motions sharply towards her  she produces a clear file with three pages of details in beautiful  clean letters   rental quotes from three companies  cheapest vs most expensive tableware  expected headcount  guest capacity differences   well  i ve summarized as much as i can   well  i ve summarized as much as i can  is printed untagged right after  sato motioned towards mii chan sharply    adjacent narration points at mii chan as the speaker  the print does not name her in the line itself  sato and matsushita poke her side when ayanokoji praises her proposal  this is head and shoulders above any proposal i ve seen so far  she still looks embarrassed and bows her head lightly to him  co planner  the three of them plus maezono planned the cafe  co planner  both tease her about the praise  guard for their demonstration  her clear file proposal wins horikita s serious review   quintessential  praise","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v5-p22-1\"><h3><span class=\"ttl\">Mii-chan: the maid-café proposal writer<\/span><span class=\"meta\">Y2V5 · p.22–24<\/span><\/h3><p class=\"setup\">Sitting in the special-wing classroom in a Chinese-style maid suit for the &quot;Maimai&quot; maid-café demonstration; shyly watching the customers. Satō motions sharply towards her; she produces a clear file with three pages of details in beautiful, clean letters — rental quotes from three companies (cheapest vs most expensive tableware), expected headcount, guest-capacity differences. Satō and Matsushita poke her side when Ayanokōji praises her proposal (&quot;This is head and shoulders above any proposal I&#x27;ve seen so far.&quot;); she still looks embarrassed and bows her head lightly to him.<\/p><p class=\"with\">with <a href=\"satou-maya.html\">Satō Maya<\/a> · <a href=\"matsushita-chiaki.html\">Matsushita Chiaki<\/a> · <a href=\"maezono.html\">Maezono<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Well, I&#x27;ve summarized as much as I can...&quot;<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> &quot;Well, I&#x27;ve summarized as much as I can...&quot; is printed untagged right after &quot;Satō motioned towards Mii-chan sharply.&quot; — adjacent narration points at Mii-chan as the speaker; the print does not name her in the line itself.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Satō Maya<\/b> Co-planner; the three of them plus Maezono planned the café.<span class=\"pg\">p.22–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matsushita Chiaki<\/b> Co-planner; both tease her about the praise.<span class=\"pg\">p.22–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Maezono<\/b> Guard for their demonstration.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her clear-file proposal wins Horikita&#x27;s serious review; &quot;quintessential&quot; praise.<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v5-p172-1\">→ After: Mii-chan: the crush revealed<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v5-p172-1","v":"y2v5","y":2,"o":21,"k":"","w":"hirata-yousuke kushida-kikyou hasebe-haruka asahina-nazuna","q":"asahina nazuna mii chan  the crush revealed present in the eye contact interrogation  watches ayanokoji confess to the 14th round  for  vote  breaks down in public    mii chan rushed over and put her hand on kushida s back    sobbing over the collapse of her composure  kushida s spear lands on her    speaking of romantic connections  wang san has been asking me for advice    the print follows with  no  please don t   her voice  reacting  and  mii chan was forced to suddenly look at the person she has a crush on in the middle of the classroom    her crush on hirata kun is outed in front of him  she turns red and breaks down  the print names her  wang san  in kushida s spear line  the roster carries both wang mei yu and asahina nazuna  the mii chan ambiguity flagged for the owner since year 2  vol  10    the print implies wang san is mii chan here  chinese surname wang   the same crush context  recorded as inference with adjacent support  owner decision pending  her long standing crush   the class knows it  kushida knows it  her secret keeper   turned prosecutor  the hawker of the group s hearts","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v5-p172-1\"><h3><span class=\"ttl\">Mii-chan: the crush revealed<\/span><span class=\"meta\">Y2V5 · p.172, 177, 184, 207<\/span><\/h3><p class=\"setup\">Present in the eye-contact interrogation. Watches Ayanokōji confess to the 14th-round &quot;for&quot; vote. Breaks down in public — &quot;Mii-chan rushed over and put her hand on Kushida&#x27;s back&quot; — sobbing over the collapse of her composure. Kushida&#x27;s spear lands on her — &quot;Speaking of romantic connections, Wang-san has been asking me for advice&quot; — the print follows with &quot;No, please don&#x27;t!&quot; (her voice, reacting) and &quot;Mii-chan was forced to suddenly look at the person she has a crush on in the middle of the classroom&quot; — her crush on Hirata-kun is outed in front of him; she turns red and breaks down.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The print names her &quot;Wang-san&quot; in Kushida&#x27;s spear line; the roster carries BOTH wang-mei-yu and asahina-nazuna (the Mii-chan ambiguity flagged for the owner since Year 2, Vol. 10) — the print implies Wang-san is Mii-chan here (Chinese surname Wang + the same crush context), recorded as inference-with-adjacent-support; owner decision pending.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Her long-standing crush — the class knows it; Kushida knows it.<span class=\"pg\">p.184–207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Her secret-keeper — turned prosecutor.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> The Hawker of the group&#x27;s hearts.<span class=\"pg\">p.184<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v5-p22-1\">← Before: Mii-chan: the maid-café proposal writer<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v6-p155-1","v":"y2v6","y":2,"o":22,"k":"spoken","w":"ayanokouji-kiyotaka hirata-yousuke kushida-kikyou asahina-nazuna","q":"asahina nazuna mii chan  persuaded to return to school visited by ayanokoji while absent   a hardworking girl who s been receiving food deliveries  from hirata  and genuinely wants to return  unlike kushida haruka   o of course not  i really want to go to school right away   not skipping is because i feel like it would be uncool to do so   i i will definitely go to school properly on monday  ashamed of her absence  kushida exposed her confession to hirata  but eager to come back  with ayanokoji s gentle reasoning  if she returns before kushida haruka she ll be fine  she resolves to return monday   and does  he persuades her to return  she trusts his reasoning  he s been secretly delivering food and is far more worried about her than about kushida haruka  on her return  kushida bluntly says she doesn t intend to get along with her   leaving mii chan frozen","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v6-p155-1\"><h3><span class=\"ttl\">Mii-chan: persuaded to return to school<\/span><span class=\"meta\">Y2V6 · p.155–161<\/span><\/h3><p class=\"setup\">Visited by Ayanokōji while absent — a hardworking girl who&#x27;s been receiving food deliveries (from Hirata) and genuinely wants to return, unlike Kushida/Haruka.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;O-of course not! I really want to go to school right away.&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">&quot;not skipping is because I feel like it would be uncool to do so.&quot;<span class=\"pg\">p.158<\/span><\/li><li class=\"q spoken\">&quot;I—I will definitely go to school properly on Monday.&quot;<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Ashamed of her absence (Kushida exposed her confession to Hirata) but eager to come back; with Ayanokōji&#x27;s gentle reasoning (if she returns before Kushida/Haruka she&#x27;ll be fine), she resolves to return Monday — and does.<span class=\"pg\">p.155–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He persuades her to return; she trusts his reasoning.<span class=\"pg\">p.155–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> He&#x27;s been secretly delivering food and is far more worried about her than about Kushida/Haruka.<span class=\"pg\">p.160<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> On her return, Kushida bluntly says she doesn&#x27;t intend to get along with her — leaving Mii-chan frozen.<span class=\"pg\">p.173–174<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-asahina-nazuna-y2v7-p34-1","v":"y2v7","y":2,"o":23,"k":"action spoken","w":"nagumo-miyabi ayanokouji-kiyotaka ichinose-honami horikita-manabu asahina-nazuna","q":"asahina nazuna the haunted house fall  the infirmary warning in the haunted house the ghost that jumps out stumbles on a step and falls over   ouch  ouch    it turns out to be asahina nazuna  a third year class a student  ayanokoji lends her a shoulder and checks her ankle   beginning to swell  walks her to the infirmary with a few curious stares  curiously stared at  the doctor treats her on the spot   oh  thank you for that    asahina  unable to stand on her own   don t worry about me  thank you  ayanokoji kun  i m sure i ll be fine after a little rest   woah what are you doing   oh  um  sure   yeah  i guess  yeah  i think i ll do that    shifting to one leg and hopping   speaking of which  ayanokoji s class was met with a disaster weren t you   yes    on the leak   if you have three or four classes with the same exhibit  it s only going to make the competition for customers much worse   oh  thank god  i didn t want to bother the class with something like this   that s not going to happen  but there s nothing better than having lots of class points  you know  there are even quite a few of my classmates that are against miyabi being hands off this time   in case you re wondering  nagumo is saying that he s going to let the nona s compete and pick one student from the class that takes first place  she said    nagumo s plan concentrates points on ichinose   you know what we were talking about earlier  right  how miyabi wasn t keeping an eye on you anymore   there was never really a clear winner between you and miyabi  was there   if that s the case  then i don t think it s over   i don t think that even matters  it s not entirely about you anymore  ayanokoji kun  miyabi could start targeting people close to you   like former student council president horikita  nagumo likes to compete  doesn t he   has nagumo ever been clearly beaten by someone or something  has he ever had a slight setback   miyabi s never stumbled  at least not to my knowledge   it would be an unquestionable fact that student council president nagumo is an excellent person  if he wasn t competent  it would be impossible for him to achieve his oaa or become student council president   that guy likes being number one  that s why he fought to be the top of this school  in the end  he even became the student council president  so he s really a man of his word   how can that be  he s never lost to anyone in particular   you mean he didn t have a good  rival   i wish we could just stop fighting in this school   i just hope nothing will happen to me   did i hear you right    on ayanokoji being  a little interested in student council president nagumo   i knew you were strange    after his confession of interest   it may have been a coincidence that we met  but maybe that s why nagumo wants to fight    her final word  she watches him by her side  three years at his side  warns that he could target people close to ayanokoji  the ankle infirmary walk  the private warning about nagumo  the  test case  framing is his  not hers  nagumo s plan concentrates points on ichinose  asahina s and  later  kanzaki s account  her  like former student council president horikita  comparison of competitors","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v7-p34-1\"><h3><span class=\"ttl\">The haunted-house fall; the infirmary warning<\/span><span class=\"meta\">Y2V7 · p.34–41<\/span><\/h3><p class=\"setup\">In the haunted house the ghost that jumps out stumbles on a step and falls over; “Ouch, ouch!!!” — it turns out to be Asahina Nazuna, a third-year Class A student.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Oh, thank you for that.” — Asahina, unable to stand on her own.<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\">“Don&#x27;t worry about me. Thank you, Ayanokōji-kun. I&#x27;m sure I&#x27;ll be fine after a little rest.”<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\">“Woah what are you doing?”<span class=\"pg\">p.36<\/span><\/li><\/ul><details class=\"more\"><summary>29 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Ayanokōji lends her a shoulder and checks her ankle — beginning to swell; walks her to the infirmary with a few curious stares; curiously stared at; the doctor treats her on the spot.<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, um, sure…”<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, I guess. Yeah, I think I&#x27;ll do that.” — shifting to one leg and hopping.<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Speaking of which, Ayanokōji&#x27;s class was met with a disaster weren&#x27;t you?”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.” — on the leak.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you have three or four classes with the same exhibit, it&#x27;s only going to make the competition for customers much worse.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, thank God. I didn&#x27;t want to bother the class with something like this.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not going to happen. But there&#x27;s nothing better than having lots of class points, you know. There are even quite a few of my classmates that are against Miyabi being hands-off this time.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In case you&#x27;re wondering, Nagumo is saying that he&#x27;s going to let the nonA&#x27;s compete and pick one student from the class that takes first place,” she said. — Nagumo&#x27;s plan concentrates points on Ichinose.<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You know what we were talking about earlier, right? How Miyabi wasn&#x27;t keeping an eye on you anymore?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There was never really a clear winner between you and Miyabi, was there?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that&#x27;s the case, then I don&#x27;t think it&#x27;s over.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think that even matters. It&#x27;s not entirely about you anymore, Ayanokōji-kun. Miyabi could start targeting people close to you.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Like former student council president Horikita, Nagumo likes to compete, doesn&#x27;t he?”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Has Nagumo ever been clearly beaten by someone or something? Has he ever had a slight setback?”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Miyabi&#x27;s never stumbled, at least not to my knowledge.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would be an unquestionable fact that Student Council President Nagumo is an excellent person. If he wasn&#x27;t competent, it would be impossible for him to achieve his OAA or become student council president.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That guy likes being number one. That&#x27;s why he fought to be the top of this school. In the end, he even became the student council president, so he&#x27;s really a man of his word.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How can that be...? He&#x27;s never lost to anyone in particular.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean he didn&#x27;t have a good... Rival?”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wish we could just stop fighting in this school.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just hope nothing will happen to me...”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did I hear you right?” — on Ayanokōji being “a little interested in Student Council President Nagumo.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I knew you were strange.” — after his confession of interest.<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It may have been a coincidence that we met, but maybe that&#x27;s why Nagumo wants to fight.” — her final word.<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She watches him by her side; three years at his side; warns that he could target people close to Ayanokōji.<span class=\"pg\">p.36–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The ankle-infirmary walk; the private warning about Nagumo; the “test case” framing is his, not hers.<span class=\"pg\">p.36–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Nagumo&#x27;s plan concentrates points on Ichinose (Asahina&#x27;s and, later, Kanzaki&#x27;s account).<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Her “like former student council president Horikita” comparison of competitors.<span class=\"pg\">p.39<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v7-p44-1\">→ After: Asahina named in passing<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v7-p44-1","v":"y2v7","y":2,"o":23,"k":"","w":"asahina-nazuna","q":"asahina nazuna asahina named in passing  seemed that he was all alone today  just as i had been informed by asahina    the narrator noted that asahina informed him of the staff room visit  passing mention","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v7-p44-1\"><h3><span class=\"ttl\">Asahina named in passing<\/span><span class=\"meta\">Y2V7 · p.44<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “seemed that he was all alone today, just as I had been informed by Asahina.” — the narrator noted that Asahina informed him of the staff room visit; passing mention.<span class=\"pg\">p.44<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v7-p34-1\">← Before: The haunted-house fall; the infirmary warning<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v9-p155-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"asahina-nazuna","q":"asahina nazuna found crying on the stairs he calls out to her on the stairwell  she starts at his voice  wipes her face and pulls his sleeve to keep him from leaving  she says she has stopped crying and explains that moeka  succhii  of class c withdrew that morning for a serious offence   this morning it was succhii  rather  moeka who quit school  suchi moeka from class c","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v9-p155-1\"><h3><span class=\"ttl\">Found crying on the stairs<\/span><span class=\"meta\">Y2V9 · p.155–157<\/span><\/h3><p class=\"setup\">He calls out to her on the stairwell; she starts at his voice, wipes her face and pulls his sleeve to keep him from leaving. She says she has stopped crying and explains that Moeka (Succhii) of Class C withdrew that morning for a serious offence.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;This morning it was Succhii— Rather, Moeka who quit school. Suchi Moeka from Class C.&quot;<span class=\"pg\">p.157<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p158-1\">→ After: The loophole and the café<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v9-p158-1","v":"y2v9","y":2,"o":25,"k":"","w":"nagumo-miyabi asahina-nazuna","q":"asahina nazuna the loophole and the cafe she tells him nagumo s contract is a loophole for lower classes  then  after his promise of secrecy  begins to explain it  she resents that nagumo did nothing about moeka s exit  close enough to him to be suspected of knowing his secrets  she resents his indifference to moeka s exit  they leave the cold corridor for a cafe in keyaki mall","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v9-p158-1\"><h3><span class=\"ttl\">The loophole and the café<\/span><span class=\"meta\">Y2V9 · p.158–159<\/span><\/h3><p class=\"setup\">She tells him Nagumo&#x27;s contract is a loophole for lower classes, then, after his promise of secrecy, begins to explain it; she resents that Nagumo did nothing about Moeka&#x27;s exit. They leave the cold corridor for a café in Keyaki Mall.<\/p><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Close enough to him to be suspected of knowing his secrets; she resents his indifference to Moeka&#x27;s exit.<span class=\"pg\">p.158–163<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p155-1\">← Before: Found crying on the stairs<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p160-1\">→ After: The contract revealed<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v9-p160-1","v":"y2v9","y":2,"o":25,"k":"","w":"asahina-nazuna","q":"asahina nazuna the contract revealed over hot tea  she checks that no one is near and lists the conditions  75  of private points to nagumo  obedience  earned points for tickets  payment before class finalisation  revocation for disobedience and a final lottery","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v9-p160-1\"><h3><span class=\"ttl\">The contract revealed<\/span><span class=\"meta\">Y2V9 · p.160–161<\/span><\/h3><p class=\"setup\">Over hot tea, she checks that no one is near and lists the conditions: 75% of private points to Nagumo, obedience, earned points for tickets, payment before class finalisation, revocation for disobedience and a final lottery.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p158-1\">← Before: The loophole and the café<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p162-1\">→ After: The objective read and Anazai<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v9-p162-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"asahina-nazuna","q":"asahina nazuna the objective read and anazai she describes yamanaka as below average  not outgoing and not popular  and is glad to be trusted with the question  she remembers kiryuin stomping a boy who tried to shield yamanaka  she names the boy anazai of class d and contacts yamanaka  who says she will come in about thirty minutes  she says she is curious about the truth too   it was anazai kun from class d  i think","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v9-p162-1\"><h3><span class=\"ttl\">The objective read and Anazai<\/span><span class=\"meta\">Y2V9 · p.162–165<\/span><\/h3><p class=\"setup\">She describes Yamanaka as below average, not outgoing and not popular, and is glad to be trusted with the question. She remembers Kiryūin stomping a boy who tried to shield Yamanaka. She names the boy Anazai of Class D and contacts Yamanaka, who says she will come in about thirty minutes; she says she is curious about the truth too.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It was Anazai-kun from Class D, I think?&quot;<span class=\"pg\">p.165<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p160-1\">← Before: The contract revealed<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p166-1\">→ After: Tachibana arrives<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v9-p166-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"ayanokouji-kiyotaka asahina-nazuna","q":"asahina nazuna tachibana arrives  what  tachibana  yes  but  tachibana kento joins them uninvited and questions ayanokoji about yamanaka  she is confused by the interruption  she listens as tachibana explains the contract s hold over the lower classes and his own role as intermediary  she tries to stop him walking out when he refuses to let his words be recorded  then asks whether ayanokoji has worked out who gave the order  trusts him enough to reveal the contract and contact yamanaka for him  emotional over her friend s exit but clear eyed and trusting   she entrusts ayanokoji with nagumo s hidden contract and helps his investigation because she is curious about the truth too","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v9-p166-1\"><h3><span class=\"ttl\">Tachibana arrives<\/span><span class=\"meta\">Y2V9 · p.166–169<\/span><\/h3><p class=\"setup\">Tachibana Kento joins them uninvited and questions Ayanokōji about Yamanaka; she is confused by the interruption. She listens as Tachibana explains the contract&#x27;s hold over the lower classes and his own role as intermediary. She tries to stop him walking out when he refuses to let his words be recorded, then asks whether Ayanokōji has worked out who gave the order.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;What? Tachibana? Yes, but…&quot;<span class=\"pg\">p.166<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Trusts him enough to reveal the contract and contact Yamanaka for him.<span class=\"pg\">p.162–169<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Emotional over her friend&#x27;s exit but clear-eyed and trusting — she entrusts Ayanokōji with Nagumo&#x27;s hidden contract and helps his investigation because she is curious about the truth too.<span class=\"pg\">p.155–169<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v9-p162-1\">← Before: The objective read and Anazai<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v11-p53-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka nagumo-miyabi asahina-nazuna","q":"asahina nazuna ch 2  ride or die nazuna rest area  just before one  bored to death with nagumo  she muscle sits into the sofa beside him as kiyotaka arrives   hey there  ayanokoji kun   yeah  i guess   i m also going to a university  like miyabi  but it will be different from his  my self scoring on the common test for the university entrance exams i took recently was just under the cut off point  and it might be a bit impossible at my level  if i can graduate from class a  i might be able to force my way in with the help of the school  but i probably won t   but ayanokoji kun hasn t done anything wrong  it s not fair that he s being targeted by you  why are you so persistent in targeting him   isn t it because she wanted to follow in her brother s footsteps   is that so  then what was her motive   wait  wait a minute  eh  what  this is a bit different from what i thought   eh  isn t that too disadvantageous for ayanokoji kun  card games are all about luck   ah  well  yeah  well  that might be true   fuka chan is always cool   wow  that s a terrible thing to say  nagumo  in this day and age  you can t complain even if you re killed   even so  your way of speaking can cause misunderstandings  you know   nagumo  this girl is  um   oh  right  you re amasawa chan  you must be pretty good to be called into miyabi s group  huh   eh  oh my gosh  it s already this late  i have to go  but feel free to consult me if you have any problems  she will go to a different university than nagumo  her own common test score fell just under the cut off  she sides with kiyotaka against the bet  she apologizes for nagumo s style  she runs off to her own duties before the amasawa talk gets deep  she rides along to the break room  she starts as his defender and ends annoyed on his behalf  she sits with him on the sofa  she bristles at his  on top among the same sex  jab  he shrugs it off","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v11-p53-1\"><h3><span class=\"ttl\">Ch.2: Ride-or-die Nazuna<\/span><span class=\"meta\">Y2V11 · p.53–63<\/span><\/h3><p class=\"setup\">Rest Area, just before one; bored to death with Nagumo; she muscle-sits into the sofa beside him as Kiyotaka arrives.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey there, Ayanokōji-kun.”<span class=\"pg\">p.53<\/span><\/li><li class=\"q spoken\">“...Yeah, I guess.”<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\">“I&#x27;m also going to a university, like Miyabi. But it will be different from his. My self-scoring on the common test for the university entrance exams I took recently was just under the cut-off point, and it might be a bit…”<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m also going to a university, like Miyabi. But it will be different from his. My self-scoring on the common test for the university entrance exams I took recently was just under the cut-off point, and it might be a bit impossible at my level. If I can graduate from Class A, I might be able to force my way in with the help of the school... but I probably won&#x27;t.”<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But Ayanokōji-kun hasn&#x27;t done anything wrong. It&#x27;s not fair that he&#x27;s being targeted by you. Why are you so persistent in targeting him?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn&#x27;t it because she wanted to follow in her brother&#x27;s footsteps?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so? Then what was her motive?”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, wait a minute. Eh, what? This is a bit different from what I thought.”<span class=\"pg\">p.57<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Isn&#x27;t that too disadvantageous for Ayanokōji-kun? Card games are all about luck.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, well, yeah... Well, that might be true.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fūka-chan is always cool.”<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow, that&#x27;s a terrible thing to say, Nagumo. In this day and age, you can&#x27;t complain even if you&#x27;re killed.”<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, your way of speaking can cause misunderstandings, you know.”<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nagumo, this girl is... um...”<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, right. You&#x27;re Amasawa-chan. You must be pretty good to be called into Miyabi&#x27;s group, huh?”<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh, oh my gosh, it&#x27;s already this late!? I have to go, but feel free to consult me if you have any problems!”<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She will go to a different university than Nagumo; her own common-test score fell just under the cut-off.<span class=\"pg\">p.55<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She sides with Kiyotaka against the bet; she apologizes for Nagumo&#x27;s style; she runs off to her own duties before the Amasawa talk gets deep.<span class=\"pg\">p.53–63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She rides along to the break room; she starts as his defender and ends annoyed on his behalf.<span class=\"pg\">p.53–63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She sits with him on the sofa; she bristles at his &quot;on top among the same sex&quot; jab; he shrugs it off.<span class=\"pg\">p.53–63<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p64-1\">→ After: Ch.2: The Asahina-senpai question<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v11-p64-1","v":"y2v11","y":2,"o":30,"k":"","w":"asahina-nazuna","q":"asahina nazuna ch 2  the asahina senpai question nazuna runs off  kiyotaka and nagumo remain   eh  oh my gosh  it s already this late  i have to go  but feel free to consult me if you have any problems    nazuna s exit line  she almost trips on her way out   amasawa smirked and leaned in towards nagumo  who was sighing in disbelief    her exit is noted in passing  she is named here only by being gone  named in passing  not present for the amasawa exchange","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v11-p64-1\"><h3><span class=\"ttl\">Ch.2: The Asahina-senpai question<\/span><span class=\"meta\">Y2V11 · p.64<\/span><\/h3><p class=\"setup\">Nazuna runs off; Kiyotaka and Nagumo remain.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Eh, oh my gosh, it&#x27;s already this late!? I have to go, but feel free to consult me if you have any problems!” — Nazuna&#x27;s exit line; she almost trips on her way out.<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Amasawa smirked and leaned in towards Nagumo, who was sighing in disbelief.” — her exit is noted in passing; she is named here only by being gone.<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in passing; not present for the Amasawa exchange.<span class=\"pg\">p.64<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p53-1\">← Before: Ch.2: Ride-or-die Nazuna<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p79-1\">→ After: Ch.2: The swings<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v11-p79-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"kiryuin-fuuka asahina-nazuna","q":"asahina nazuna ch 2  the swings after the koenji affair  she and kiryuin are found swinging at the east park  happily talking futures  kiyotaka is dragged in   we don t usually have a chance to talk  so it s kind of fresh  really unusual  isn t it   we were talking about various things  but right now  we were talking about our future plans  i was curious about fuka chan s future   eh  isn t that a bit of a waste  you seem like you could become anything   so you don t have a dream   then tell me  i might aim for it too   what s the name of the politician  do i know him   eh  kijima  eh  the prime minister   whether it s miyabi or fuka chan  inviting ayanokoji kun  it must be something special  huh   see you later  she s angling for kiryuin s admiration  she learns the politician dream and its source  she nearly face plants running off  kiryuin tells her about kijima  asahina takes in every word of her confession about never becoming anyone","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v11-p79-1\"><h3><span class=\"ttl\">Ch.2: The swings<\/span><span class=\"meta\">Y2V11 · p.79–83<\/span><\/h3><p class=\"setup\">After the Kōenji affair; she and Kiryūin are found swinging at the east park; happily talking futures; Kiyotaka is dragged in.<\/p><p class=\"with\">with <a href=\"kiryuin-fuuka.html\">Kiryuin Fuuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“We don&#x27;t usually have a chance to talk, so it&#x27;s kind of fresh... Really unusual, isn&#x27;t it?”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“We were talking about various things, but right now, we were talking about our future plans. I was curious about Fūka-chan&#x27;s future.”<span class=\"pg\">p.80<\/span><\/li><li class=\"q spoken\">“Eh~ Isn&#x27;t that a bit of a waste? You seem like you could become anything.”<span class=\"pg\">p.81<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “So you don&#x27;t have a dream?”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then tell me. I might aim for it too.”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s the name of the politician? Do I know him?”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh, Kijima? Eh? The Prime Minister?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whether it&#x27;s Miyabi or Fūka-chan, inviting Ayanokōji-kun, it must be something special, huh?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “See you later!”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She&#x27;s angling for Kiryūin&#x27;s admiration; she learns the politician dream and its source; she nearly face-plants running off.<span class=\"pg\">p.79–83<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kiryuin Fuuka<\/b> Kiryūin tells her about Kijima; Asahina takes in every word of her confession about never becoming anyone.<span class=\"pg\">p.79–83<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p64-1\">← Before: Ch.2: The Asahina-senpai question<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p177-1\">→ After: Ch.7: The precious Asahina-senpai<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v11-p177-1","v":"y2v11","y":2,"o":30,"k":"","w":"asahina-nazuna","q":"asahina nazuna ch 7  the precious asahina senpai the 1 a m  cafeteria summons  kiyotaka does not participate  the scene is nagumo s pov   i would ve beaten up your precious asahina senpai  nagumo senpai    amasawa s threat  asahina is treated as precious  named as the threatened party  not present on these pages","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v11-p177-1\"><h3><span class=\"ttl\">Ch.7: The precious Asahina-senpai<\/span><span class=\"meta\">Y2V11 · p.177<\/span><\/h3><p class=\"setup\">The 1 a.m. cafeteria summons; Kiyotaka does not participate (the scene is Nagumo&#x27;s POV).<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “I would’ve beaten up your precious Asahina-senpai, Nagumo-senpai.” — Amasawa&#x27;s threat; Asahina is treated as precious.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named as the threatened party; not present on these pages.<span class=\"pg\">p.177<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p79-1\">← Before: Ch.2: The swings<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p178-1\">→ After: Ch.7: The precious Asahina-senpai<\/button><\/div><\/article>"},{"i":"sc-asahina-nazuna-y2v11-p178-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"amasawa-ichika asahina-nazuna","q":"asahina nazuna ch 7  the precious asahina senpai the 1 a m  cafeteria confrontation  asahina is named by amasawa as the hostage in the threat   i would ve beaten up your precious asahina senpai  nagumo senpai  she threatens to beat up asahina   as leverage  not as the target  she respects asahina as nagumo s precious person  the vendetta is not against her  named as the threatened hostage  not present on these pages","h":"<article class=\"card\" id=\"sc-asahina-nazuna-y2v11-p178-1\"><h3><span class=\"ttl\">Ch.7: The precious Asahina-senpai<\/span><span class=\"meta\">Y2V11 · p.178–179<\/span><\/h3><p class=\"setup\">The 1 a.m. cafeteria confrontation; Asahina is named by Amasawa as the hostage in the threat.<\/p><p class=\"with\">with <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “I would&#x27;ve beaten up your precious Asahina-senpai, Nagumo-senpai.”<span class=\"pg\">p.179<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She threatens to beat up Asahina — as leverage, not as the target; she respects Asahina as Nagumo&#x27;s precious person; the vendetta is not against her.<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named as the threatened hostage; not present on these pages.<span class=\"pg\">p.179<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-asahina-nazuna-y2v11-p177-1\">← Before: Ch.7: The precious Asahina-senpai<\/button><\/div><\/article>"}];
